dtsPropsFor.ContactForm:
/** Google reCAPTCHA v2 site key, passed straight to the captcha widget. */
RECAPTCHA_SITE_KEY: string;
/** The captcha only renders when this is exactly "production". Any other value renders the form without it. */
NODE_ENV: string;

dtsPropsFor.DynamicBrandedIcon:
/** Icon name from react-icons/fa6, e.g. "FaGithub" | "FaLinkedin" | "FaXTwitter". An unknown name falls back to FaUser rather than throwing. */
name: string;
/** Forwarded to the underlying react-icons element. */
size?: string | number;
color?: string;
className?: string;
title?: string;

dtsPropsFor.EducationHistory:
educationHistoryData: Array<{
  id: string;
  course: string;
  organizationId: string;
  /** Free-text range as authored in Notion, e.g. "Feb 2011 - Dec 2015". */
  date: string;
  description: Array<{
    id: string;
    type: "text" | "mention" | "equation";
    text?: { content: string; link?: { url?: string } };
    equation?: string;
    annotations: {
      bold: boolean;
      italic: boolean;
      strikethrough: boolean;
      underline: boolean;
      code: boolean;
      color: "default" | "gray" | "brown" | "orange" | "yellow" | "green" | "blue" | "purple" | "pink" | "red" | "gray_background" | "brown_background" | "orange_background" | "yellow_background" | "green_background" | "blue_background" | "purple_background" | "pink_background" | "red_background";
    };
  }>;
}>;
/** Organizations keyed by id. Every entry's organizationId must resolve here — a miss throws while rendering the logo. */
organizationsDataHash: { [key: string]: { id: string; name: string; logo: string; link: string } };

